<?php
declare(strict_types=1); session_start();
$db=new PDO('sqlite:'.__DIR__.'/velora.sqlite');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT UNIQUE, password TEXT, username TEXT UNIQUE, verified INTEGER DEFAULT 0, verify_code TEXT, created_at TEXT); CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY, display_name TEXT, bio TEXT, avatar TEXT, banner TEXT, theme TEXT DEFAULT "violet", blocks TEXT DEFAULT "[]", views INTEGER DEFAULT 0);');
$path=trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$username='';if($path&&$path!=='index.php')$username=basename($path);
if($username){$q=$db->prepare('SELECT u.username,p.* FROM users u JOIN profiles p ON p.user_id=u.id WHERE u.username=?');$q->execute([$username]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p){http_response_code(404);$p=['username'=>$username,'display_name'=>'Profil nenalezen','bio'=>'Tento profil zatím neexistuje.','theme'=>'violet','blocks'=>'[]','views'=>0];}else{$db->prepare('UPDATE profiles SET views=views+1 WHERE user_id=?')->execute([$p['user_id']]);$p['views']++;}$blocks=json_decode($p['blocks']?:'[]',true);?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($p['display_name'])?> — Velora</title><link rel="stylesheet" href="/app.css"></head><body class="public t-<?=htmlspecialchars($p['theme'])?>"><a class="wordmark" href="/">✦ velora</a><main class="public-card"><div class="public-banner" style="<?=!empty($p['banner'])?'background-image:url('.htmlspecialchars($p['banner']).')':''?>"></div><div class="public-main"><?php if(!empty($p['avatar'])):?><img class="public-avatar" src="<?=htmlspecialchars($p['avatar'])?>"><?php else:?><div class="public-avatar placeholder"><?=strtoupper(substr($p['display_name'],0,1))?></div><?php endif?><h1><?=htmlspecialchars($p['display_name'])?></h1><span class="handle">/<?=htmlspecialchars($p['username'])?></span><p><?=nl2br(htmlspecialchars($p['bio']))?></p><div class="blocks"><?php foreach($blocks as $b):?><a class="public-block" href="<?=htmlspecialchars($b['url']??'#')?>" target="_blank"><span><?=htmlspecialchars($b['icon']??'↗')?></span><strong><?=htmlspecialchars($b['title']??'Odkaz')?></strong><i>↗</i></a><?php endforeach?></div><footer>◉ <?=number_format((int)$p['views'],0,',',' ')?> návštěv <span>vytvořeno na <b>velora</b></span></footer></div></main></body></html><?php exit;}?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color"